-- Speech practice taxonomy and reviewed source-bank drafts. All imported lines remain DRAFT until audio is reviewed.

create table if not exists public.speech_practice_categories (id uuid primary key default gen_random_uuid(), prompt_type text not null check (prompt_type = 'SHADOWING'), name text not null check (length(trim(name)) between 1 and 120), sort_order integer not null default 0, created_at timestamptz not null default now(), unique (prompt_type, name));

alter table public.speech_practice_categories enable row level security;

revoke all on public.speech_practice_categories from anon, authenticated;

grant all on public.speech_practice_categories to service_role;

alter table public.speech_practice_prompts add column if not exists category_id uuid references public.speech_practice_categories(id) on delete set null;

alter table public.speech_practice_prompts add column if not exists difficulty text check (difficulty is null or difficulty in ('EASY','MODERATE','DIFFICULT','VERY_DIFFICULT'));

alter table public.speech_practice_prompts add column if not exists source_key text;

create unique index if not exists speech_practice_prompts_source_key_idx on public.speech_practice_prompts(source_key) where source_key is not null;

create index if not exists speech_practice_categories_picker_idx on public.speech_practice_categories(prompt_type, sort_order, name);

