insert into public.speech_practice_prompts (source_key, prompt_type, title, text, category_id, cefr_level, difficulty, target_sounds, tags, audio_variants, status)
select b.source_key, b.prompt_type, b.title, b.text, b.category_id, b.cefr_level, b.difficulty, b.target_sounds, array[]::text[], '{}'::jsonb, 'DRAFT'
from bank b
where not exists (select 1 from public.speech_practice_prompts p where p.prompt_type=b.prompt_type and p.text=b.text)
on conflict (source_key) where source_key is not null do update set category_id=excluded.category_id, difficulty=excluded.difficulty, target_sounds=excluded.target_sounds;
